"""Regenerate barycorrpy_zb.txt: barycorrpy's c*z_B for the raw-redshift test.

Run in a THROWAWAY environment that has barycorrpy (it is not an EXOZIPPy
dependency and must not become one):

    python -m venv /some/scratch/bcvenv
    /some/scratch/bcvenv/bin/pip install barycorrpy jplephem
    /some/scratch/bcvenv/bin/python make_barycorrpy_fixture.py

barycorrpy (Kanodia & Wright 2018) implements Wright & Eastman (2014) with
the JPL DE430 ephemeris.  Its get_BC_vel(..., zmeas=0) returns c*z_B, the
barycentric correction in the convention 1 + z_true = (1 + z_B)(1 + z_meas).
tests/test_raw_redshift.py compares EXOZIPPy's redshift.barycentric_redshift
against these numbers.  The cases (sites, stars, epochs) are defined here
and read back by the test from the file itself, so the two cannot drift.
"""

import numpy as np
from astropy.time import Time

# (name, ra deg, dec deg, pmra mas/yr, pmdec mas/yr, parallax mas, rv m/s,
#  epoch JD).  Barnard's star and tau Ceti from Gaia DR3 (J2016.0);
#  Barnard's again at J2000 (Hipparcos-era values) to put 25 yr of proper
#  motion between the epoch and the data; a Gaia-4-like star with an
#  ASSUMED systemic rv (illustrative, not a measurement).
STARS = [
    (
        "Barnard",
        269.44850252,
        4.73942005,
        -801.551,
        10362.394,
        546.9759,
        -110110.0,
        2457389.0,
    ),
    (
        "Gaia4like",
        209.5063,
        31.6955,
        -75.53,
        17.97,
        13.63,
        -20000.0,
        2457389.0,
    ),
    (
        "tauCet",
        26.00930287,
        -15.93379865,
        -1729.726,
        855.493,
        273.8097,
        -16597.0,
        2457389.0,
    ),
    (
        "BarnardJ2000",
        269.4520769,
        4.6933649,
        -798.58,
        10328.12,
        548.31,
        -110510.0,
        2451545.0,
    ),
]
# (name, East longitude deg, latitude deg, height m)
SITES = [
    ("McDonald", -104.0147, 30.6814, 2026.0),
    ("KittPeak", -111.6003, 31.9583, 2091.0),
    ("LaPalma", -17.8850, 28.7577, 2382.0),
    ("Paranal", -70.4045, -24.6272, 2635.0),
]
JD_UTC = np.sort(np.random.default_rng(1).uniform(2457000.0, 2461300.0, 40))

if __name__ == "__main__":
    import barycorrpy
    from barycorrpy import get_BC_vel

    lines = [
        f"# barycorrpy {barycorrpy.__version__ if hasattr(barycorrpy, '__version__') else ''} get_BC_vel(zmeas=0, ephemeris='de430'): c*z_B [m/s]",
        "# generated by make_barycorrpy_fixture.py (see its docstring)",
        "# STAR name ra dec pmra pmdec px rv epoch",
    ]
    lines += ["# STAR " + " ".join(str(v) for v in s) for s in STARS]
    lines += ["# SITE " + " ".join(str(v) for v in s) for s in SITES]
    lines.append("# columns: site_index star_index JD_UTC c*z_B[m/s]")
    for a, (_, lon, lat, alt) in enumerate(SITES):
        for b, (_, ra, dec, pmra, pmdec, px, rv, ep) in enumerate(STARS):
            v, _, _ = get_BC_vel(
                Time(JD_UTC, format="jd", scale="utc"),
                ra=ra,
                dec=dec,
                epoch=ep,
                pmra=pmra,
                pmdec=pmdec,
                px=px,
                rv=rv,
                lat=lat,
                longi=lon,
                alt=alt,
                zmeas=0.0,
                ephemeris="de430",
                leap_update=False,
            )
            for t, vb in zip(JD_UTC, np.asarray(v, float)):
                lines.append(f"{a} {b} {t:.10f} {vb:.6f}")
    with open("barycorrpy_zb.txt", "w") as fh:
        fh.write("\n".join(lines) + "\n")
